type User = { id: number; name: string };
const users: User[] = [{ id: 1, name: 'An' }];

// Guard the possibly-undefined result before reading .name.
export function nameOf(id: number): string {
  const u = users.find((x) => x.id === id);
  return u?.name ?? 'unknown';
}

import { nameOf } from '../src/find.ts';
const n: string = nameOf(1);
export { n };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { nameOf } from '../src/find.ts';
test('nameOf', () => { assert.equal(nameOf(1), 'An'); assert.equal(nameOf(99), 'unknown'); });

