type Config = { host: string; port?: number };

// config.port may be undefined, so returning it as a number is refused.
export function resolvePort(config: Config): number {
  return config.port;
}

import { resolvePort } from '../src/config.ts';
const p: number = resolvePort({ host: 'localhost' });
export { p };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { resolvePort } from '../src/config.ts';
test('resolvePort', () => { assert.equal(resolvePort({ host: 'x' }), 5432); assert.equal(resolvePort({ host: 'x', port: 3000 }), 3000); });

